WITH flagged AS (SELECT *, CASE WHEN LAG(txn_time) OVER (PARTITION BY account_id ORDER BY txn_time ASC, id ASC) IS NULL OR txn_time > LAG(txn_time) OVER (PARTITION BY account_id ORDER BY txn_time ASC, id ASC) + INTERVAL 14 DAYS THEN 1 ELSE 0 END AS session_start_flag FROM transactions), sessionized AS (SELECT id, account_id, txn_type, amount, txn_time, is_flagged, SUM(session_start_flag) OVER (PARTITION BY account_id ORDER BY txn_time ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_id FROM flagged) SELECT s.id, s.account_id, s.txn_type, s.amount, s.txn_time, s.is_flagged, s.session_id, CASE WHEN txn_type RLIKE '^(REFUND|FEE)$' THEN 'OTHER_ZONE' ELSE 'EXTENDED' END AS txn_type_zone, (SELECT AVG(t2.amount) FROM transactions t2 WHERE t2.account_id = s.account_id) AS avg_transaction_amount FROM sessionized s ORDER BY amount ASC NULLS LAST;
